$('.fn#parse_config > .jump#return').parent().filter(':has(.jump#return)').each(function() {
    var parent = $(this).parent();
    if (parent.is('.if') || parent.is('.try') || parent.is('.with_statement')) {
        return parent;
    }
});

$('.fn#calculate_total > .jump#return').parent().filter(':has(.jump#return)').each(function() {
    var parent = $(this);
    if (parent.is('.if') || parent.is('.try') || parent.is('.loop')) {
        parent.remove();
    }
});
